import 'dart:convert';
import 'dart:io';

import 'package:crypto/crypto.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:maxstream/services/release_checksum.dart';

void main() {
  group('findSha256ForFile', () {
    const sums = '''
# generated by sha256sum
2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  maxstream-arm64-v8a.apk
a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447 *maxstream-tv.apk

ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789  MaxStream-Dex.exe
''';

    test('returns the checksum for an exact filename', () {
      expect(
        findSha256ForFile(sums, 'maxstream-arm64-v8a.apk'),
        '2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824',
      );
    });

    test('handles the binary marker and normalises case', () {
      expect(
        findSha256ForFile(sums, 'maxstream-tv.apk'),
        'a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447',
      );
      expect(
        findSha256ForFile(sums, 'MaxStream-Dex.exe'),
        'abcdef0123456789abcdef0123456789abcdef0123456789abcdef0123456789',
      );
    });

    test('accepts path-prefixed entries', () {
      expect(
        findSha256ForFile(
          '2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  release-assets/maxstream-tv.apk',
          'maxstream-tv.apk',
        ),
        '2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824',
      );
    });

    test('returns null for a missing file or malformed input', () {
      expect(findSha256ForFile(sums, 'maxstream-x86_64.apk'), isNull);
      expect(findSha256ForFile('', 'maxstream-tv.apk'), isNull);
      expect(
        findSha256ForFile('not a checksum line', 'maxstream-tv.apk'),
        isNull,
      );
    });
  });

  group('sha256OfFile', () {
    late Directory tempDir;

    setUp(() async {
      tempDir = await Directory.systemTemp.createTemp('maxstream-sha256-');
    });

    tearDown(() async {
      if (await tempDir.exists()) await tempDir.delete(recursive: true);
    });

    test('hashes a small file', () async {
      final file = File('${tempDir.path}/hello.txt');
      await file.writeAsString('hello');
      expect(
        await sha256OfFile(file),
        '2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824',
      );
    });

    test('streams large files across multiple chunks', () async {
      final bytes = List<int>.generate(1024 * 1024 + 17, (i) => i % 251);
      final file = File('${tempDir.path}/large.bin');
      await file.writeAsBytes(bytes);
      expect(await sha256OfFile(file), sha256.convert(bytes).toString());
    });

    test('encoding does not depend on text decoding', () async {
      final bytes = utf8.encode('MaxStream ✓ update');
      final file = File('${tempDir.path}/utf8.txt');
      await file.writeAsBytes(bytes);
      expect(await sha256OfFile(file), sha256.convert(bytes).toString());
    });
  });
}
